using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Text;
using System;
using System.Collections.Generic;
using System.Collections.Immutable;
using System.IO;
using System.Linq;
using System.Text;

namespace FluentUI.FontMapper;

[Generator]
public sealed class FontMapperGenerator : IIncrementalGenerator
{
    public const string AttributeName = "FluentUI.FontMapper.FontMapperAttribute";

    private const string AttributeSource = """
        // <auto-generated/>
        using System;

        namespace FluentUI.FontMapper
        {
            /// <summary>
            /// Generates glyph string constants from a TrueType font.
            /// Use the single-argument constructor on a partial class, or the three-argument constructor at assembly scope.
            /// The font must be included as an AdditionalFiles item so changes rebuild the constants.
            /// </summary>
            [AttributeUsage(AttributeTargets.Assembly | AttributeTargets.Class, AllowMultiple = true, Inherited = false)]
            internal sealed class FontMapperAttribute : Attribute
            {
                public FontMapperAttribute(string fontPath)
                {
                    FontPath = fontPath;
                }

                public FontMapperAttribute(string fontPath, string className, string @namespace)
                {
                    FontPath = fontPath;
                    ClassName = className;
                    Namespace = @namespace;
                }

                public string FontPath { get; }

                public string? ClassName { get; }

                public string? Namespace { get; }
            }
        }
        """;

    public void Initialize(IncrementalGeneratorInitializationContext context)
    {
        context.RegisterPostInitializationOutput(static output =>
        {
            output.AddSource("FontMapperAttribute.g.cs", SourceText.From(AttributeSource, Encoding.UTF8));
        });

        var requests = context.SyntaxProvider
            .CreateSyntaxProvider(
                static (node, _) => node is AttributeSyntax attribute && IsFontMapperAttribute(attribute),
                static (syntaxContext, _) => CreateRequest(syntaxContext))
            .Where(static request => request != null)
            .Select(static (request, _) => request!.Value)
            .Collect();

        var additionalFiles = context.AdditionalTextsProvider
            .Select(static (text, _) => text.Path)
            .Collect();

        var projectDirectory = context.AnalyzerConfigOptionsProvider
            .Select(static (provider, _) =>
            {
                provider.GlobalOptions.TryGetValue("build_property.projectdir", out var directory);
                return directory ?? string.Empty;
            });

        var generation = requests
            .Combine(additionalFiles)
            .Combine(projectDirectory);

        context.RegisterSourceOutput(generation, static (output, input) =>
        {
            var requests = input.Left.Left;
            var files = input.Left.Right;
            var projectDir = input.Right;
            Generate(output, requests, files, projectDir);
        });
    }

    private static bool IsFontMapperAttribute(AttributeSyntax attribute)
    {
        var name = attribute.Name.ToString();
        return name is "FontMapper"
            or "FontMapperAttribute"
            or "FluentUI.FontMapper.FontMapper"
            or "FluentUI.FontMapper.FontMapperAttribute";
    }

    private static GenerationRequest? CreateRequest(GeneratorSyntaxContext context)
    {
        var attribute = (AttributeSyntax)context.Node;
        var argumentList = attribute.ArgumentList;
        if (argumentList == null)
        {
            return GenerationRequest.Invalid(attribute.GetLocation(), assembly: false);
        }

        var arguments = argumentList.Arguments;

        var list = attribute.Parent as AttributeListSyntax;
        var assembly = list?.Target?.Identifier.IsKind(SyntaxKind.AssemblyKeyword) == true;
        if (assembly)
        {
            if (arguments.Count != 3)
            {
                return GenerationRequest.Invalid(attribute.GetLocation(), assembly: true);
            }

            return GenerationRequest.ForAssembly(
                ConstantString(context, arguments[0]) ?? string.Empty,
                ConstantString(context, arguments[1]) ?? string.Empty,
                ConstantString(context, arguments[2]) ?? string.Empty,
                attribute.GetLocation());
        }

        if (list?.Parent is not ClassDeclarationSyntax declaration)
        {
            return GenerationRequest.Invalid(attribute.GetLocation(), assembly: false);
        }

        if (arguments.Count != 1)
        {
            return GenerationRequest.Invalid(attribute.GetLocation(), assembly: false);
        }

        return GenerationRequest.ForClass(
            ConstantString(context, arguments[0]) ?? string.Empty,
            declaration,
            attribute.GetLocation());
    }

    private static string? ConstantString(GeneratorSyntaxContext context, AttributeArgumentSyntax argument)
    {
        if (argument.Expression is LiteralExpressionSyntax literal && literal.Token.Value is string text)
        {
            return text;
        }

        var value = context.SemanticModel.GetConstantValue(argument.Expression);
        return value.HasValue ? value.Value as string : null;
    }

    private static void Generate(
        SourceProductionContext output,
        ImmutableArray<GenerationRequest> requests,
        ImmutableArray<string> additionalFiles,
        string projectDirectory)
    {
        var seen = new HashSet<string>(StringComparer.Ordinal);
        foreach (var request in requests)
        {
            if (!string.IsNullOrEmpty(request.Error))
            {
                output.ReportDiagnostic(Diagnostic.Create(Diagnostics.InvalidUsage, request.Location, request.Error));
                continue;
            }

            if (!request.IsPartial)
            {
                output.ReportDiagnostic(Diagnostic.Create(Diagnostics.ClassMustBePartial, request.Location, request.ClassName));
                continue;
            }

            if (!IsIdentifier(request.ClassName) || !IsNamespace(request.NamespaceName))
            {
                output.ReportDiagnostic(Diagnostic.Create(Diagnostics.InvalidName, request.Location, request.ClassName, request.NamespaceName));
                continue;
            }

            var key = request.NamespaceName + "." + request.ClassName;
            if (!seen.Add(key))
            {
                output.ReportDiagnostic(Diagnostic.Create(Diagnostics.DuplicateClass, request.Location, key));
                continue;
            }

            var resolved = ResolvePath(request.FontPath, additionalFiles, projectDirectory);
            if (resolved == null || !File.Exists(resolved))
            {
                output.ReportDiagnostic(Diagnostic.Create(Diagnostics.FontNotFound, request.Location, request.FontPath));
                continue;
            }

            List<GlyphMapping> glyphs;
            try
            {
                glyphs = FontFile.Read(File.ReadAllBytes(resolved));
            }
            catch (Exception exception) when (exception is InvalidDataException or IOException or ArgumentException)
            {
                output.ReportDiagnostic(Diagnostic.Create(Diagnostics.FontUnreadable, request.Location, request.FontPath, exception.Message));
                continue;
            }

            if (glyphs.Count == 0)
            {
                output.ReportDiagnostic(Diagnostic.Create(Diagnostics.NoGlyphs, request.Location, request.FontPath));
                continue;
            }

            var named = GlyphNamer.Name(glyphs);
            var source = CodeEmitter.Emit(request.NamespaceName, request.Types, named, request.FontPath);
            output.AddSource(SanitizeFileName(key) + ".g.cs", SourceText.From(source, Encoding.UTF8));
        }
    }

    internal static string? ResolvePath(string requested, IReadOnlyList<string> additionalFiles, string? projectDirectory)
    {
        if (string.IsNullOrWhiteSpace(requested))
        {
            return null;
        }

        var normalizedRequest = requested.Replace('\\', '/').TrimStart('/');
        string? match = null;
        foreach (var candidate in additionalFiles)
        {
            if (string.IsNullOrEmpty(candidate))
            {
                continue;
            }

            var normalized = candidate.Replace('\\', '/');
            var matches = normalized.Equals(normalizedRequest, StringComparison.OrdinalIgnoreCase)
                || normalized.EndsWith("/" + normalizedRequest, StringComparison.OrdinalIgnoreCase);
            if (matches)
            {
                match = candidate;
            }
        }

        if (match != null && File.Exists(match))
        {
            return match;
        }

        if (Path.IsPathRooted(requested) && File.Exists(requested))
        {
            return requested;
        }

        if (!string.IsNullOrEmpty(projectDirectory))
        {
            var combined = Path.Combine(projectDirectory, requested);
            if (File.Exists(combined))
            {
                return combined;
            }
        }

        if (File.Exists(requested))
        {
            return Path.GetFullPath(requested);
        }

        return match;
    }

    private static bool IsIdentifier(string name)
    {
        if (string.IsNullOrEmpty(name))
        {
            return false;
        }

        if (!(char.IsLetter(name[0]) || name[0] == '_'))
        {
            return false;
        }

        for (var i = 1; i < name.Length; i++)
        {
            if (!(char.IsLetterOrDigit(name[i]) || name[i] == '_'))
            {
                return false;
            }
        }

        return true;
    }

    private static bool IsNamespace(string name)
    {
        if (string.IsNullOrEmpty(name))
        {
            return true;
        }

        var parts = name.Split('.');
        if (parts.Length == 0)
        {
            return false;
        }

        foreach (var part in parts)
        {
            var identifier = part.StartsWith("@", StringComparison.Ordinal) ? part.Substring(1) : part;
            if (!IsIdentifier(identifier))
            {
                return false;
            }
        }

        return true;
    }

    private static string SanitizeFileName(string name)
    {
        var builder = new StringBuilder(name.Length);
        foreach (var character in name)
        {
            builder.Append(char.IsLetterOrDigit(character) ? character : '_');
        }

        return builder.ToString();
    }
}

internal readonly struct GenerationRequest
{
    private GenerationRequest(
        string fontPath,
        string className,
        string namespaceName,
        bool isPartial,
        ImmutableArray<TypePart> types,
        Location location,
        string error)
    {
        FontPath = fontPath;
        ClassName = className;
        NamespaceName = namespaceName;
        IsPartial = isPartial;
        Types = types;
        Location = location;
        Error = error;
    }

    public string FontPath { get; }

    public string ClassName { get; }

    public string NamespaceName { get; }

    public bool IsPartial { get; }

    public ImmutableArray<TypePart> Types { get; }

    public Location Location { get; }

    public string Error { get; }

    public static GenerationRequest ForAssembly(string fontPath, string className, string namespaceName, Location location)
    {
        return new GenerationRequest(
            fontPath,
            className,
            namespaceName,
            true,
            [new TypePart("public static partial", className)],
            location,
            string.Empty);
    }

    public static GenerationRequest ForClass(string fontPath, ClassDeclarationSyntax declaration, Location location)
    {
        var nested = new List<ClassDeclarationSyntax>();
        for (SyntaxNode? current = declaration; current != null; current = current.Parent)
        {
            if (current is ClassDeclarationSyntax type)
            {
                nested.Add(type);
            }
        }

        nested.Reverse();
        var types = nested.Select(static type => new TypePart(ClassModifiers(type), type.Identifier.ValueText)).ToImmutableArray();
        return new GenerationRequest(
            fontPath,
            declaration.Identifier.ValueText,
            ReadNamespace(declaration),
            declaration.Modifiers.Any(static modifier => modifier.IsKind(SyntaxKind.PartialKeyword)),
            types,
            location,
            string.Empty);
    }

    public static GenerationRequest Invalid(Location location, bool assembly)
    {
        var message = assembly
            ? "Assembly usage is [assembly: FontMapper(\"font.ttf\", \"ClassName\", \"Namespace\")]"
            : "Class usage is [FontMapper(\"font.ttf\")] on a partial class";
        return new GenerationRequest(string.Empty, string.Empty, string.Empty, true, [], location, message);
    }

    private static string ReadNamespace(SyntaxNode node)
    {
        var names = new List<string>();
        for (var current = node.Parent; current != null; current = current.Parent)
        {
            if (current is BaseNamespaceDeclarationSyntax namespaceDeclaration)
            {
                names.Add(namespaceDeclaration.Name.ToString());
            }
        }

        names.Reverse();
        return string.Join(".", names);
    }

    private static string ClassModifiers(ClassDeclarationSyntax declaration)
    {
        var modifiers = declaration.Modifiers
            .Where(static modifier => !modifier.IsKind(SyntaxKind.PartialKeyword))
            .Select(static modifier => modifier.ValueText);
        var text = string.Join(" ", modifiers);
        return text.Length == 0 ? "partial" : text + " partial";
    }
}

internal static class Diagnostics
{
    public static readonly DiagnosticDescriptor FontNotFound = new(
        "FM0001",
        "Font file not found",
        "Font file '{0}' was not found. Include it as an AdditionalFiles item or place it in the project directory.",
        "FontMapper",
        DiagnosticSeverity.Error,
        isEnabledByDefault: true);

    public static readonly DiagnosticDescriptor FontUnreadable = new(
        "FM0002",
        "Font file could not be read",
        "Font file '{0}' could not be read: {1}",
        "FontMapper",
        DiagnosticSeverity.Error,
        isEnabledByDefault: true);

    public static readonly DiagnosticDescriptor ClassMustBePartial = new(
        "FM0003",
        "Font mapper class must be partial",
        "Class '{0}' must be partial so the generator can add glyph strings",
        "FontMapper",
        DiagnosticSeverity.Error,
        isEnabledByDefault: true);

    public static readonly DiagnosticDescriptor NoGlyphs = new(
        "FM0004",
        "Font has no named glyphs",
        "Font file '{0}' does not contain named Unicode glyphs",
        "FontMapper",
        DiagnosticSeverity.Error,
        isEnabledByDefault: true);

    public static readonly DiagnosticDescriptor InvalidName = new(
        "FM0005",
        "Invalid generated type name",
        "Cannot generate class '{0}' in namespace '{1}'",
        "FontMapper",
        DiagnosticSeverity.Error,
        isEnabledByDefault: true);

    public static readonly DiagnosticDescriptor DuplicateClass = new(
        "FM0006",
        "Duplicate generated class",
        "More than one font is mapped to '{0}'",
        "FontMapper",
        DiagnosticSeverity.Error,
        isEnabledByDefault: true);

    public static readonly DiagnosticDescriptor InvalidUsage = new(
        "FM0007",
        "Invalid FontMapper usage",
        "{0}",
        "FontMapper",
        DiagnosticSeverity.Error,
        isEnabledByDefault: true);
}
